:root {
  /* Font families */
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-serif: Charter, "Bitstream Charter", "Sitka Text", Cambria, serif;
  --font-mono: ui-monospace, "Cascadia Code", "Source Code Pro", Menlo, monospace;

  /* Font metrics normalization — themes with different font families
     (monospace, pixel, etc.) can set this to normalize x-height ratios,
     reducing heading wrapping differences across themes */
  --font-size-adjust: none;

  /* Non-Latin font family slots — override via @font-face or system fonts */
  --font-cjk: "Noto Sans CJK SC", "PingFang SC", "Hiragino Sans", "Yu Gothic", system-ui, sans-serif;
  /* CJK alternate voice (<i>): calligraphic kai / mincho faces */
  --font-cjk-alternate: "Kaiti SC", "STKaiti", "KaiTi", "BiauKai", "DFKai-SB", "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK SC", serif;
  --font-arabic: "Noto Sans Arabic", "Segoe UI", system-ui, sans-serif;
  --font-hebrew: "Noto Sans Hebrew", "Segoe UI", system-ui, sans-serif;
  --font-thai: "Noto Sans Thai", "Leelawadee UI", system-ui, sans-serif;
  --font-devanagari: "Noto Sans Devanagari", "Devanagari Sangam MN", system-ui, sans-serif;

  /* Font size scale - Open Props aligned */
  --font-size-2xs: 0.625rem;  /* 10px - dense UI: calendars, wireframe labels */
  --font-size-xs: 0.75rem;    /* 12px */
  --font-size-s: 0.875rem;   /* 14px */
  --font-size-m: 1rem;       /* 16px - base */
  --font-size-l: 1.125rem;   /* 18px */
  --font-size-xl: 1.25rem;    /* 20px */
  --font-size-2xl: 1.5rem;    /* 24px */
  --font-size-3xl: 1.875rem;  /* 30px */
  --font-size-4xl: 2.25rem;   /* 36px */
  --font-size-5xl: 3rem;      /* 48px */

  /* Line height scale - Open Props aligned */
  --line-height-none: 1;
  --line-height-tight: 1.25;
  --line-height-snug: 1.375;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.625;
  --line-height-loose: 1.75;

  /* Body line-height unit — useful for prose vertical rhythm */
  --lh: 1.5rem;

  /* Measure (line length) */
  --measure-narrow: 45ch;
  --measure-normal: 65ch;
  --measure-wide: 80ch;

  /* Prose reading tokens — consumed by article.blog, [data-prose], layout-text */
  --prose-measure: 65ch;
  --prose-line-height: 1.6;

  /* Font weights */
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Letter spacing */
  --letter-spacing-tight: -0.025em;
  --letter-spacing-normal: 0;
  --letter-spacing-wide: 0.025em;
  --letter-spacing-wider: 0.05em;
}
