chat-bubble {
  display: block;
  padding: var(--size-s) var(--size-m);
  border-radius: var(--chat-bubble-radius, var(--radius-m));
  line-height: var(--line-height-relaxed, 1.6);
  overflow-wrap: anywhere;

  /* Typography within bubble */
  & > p {
    margin: 0;

    & + p {
      margin-block-start: var(--size-xs);
    }
  }

  /* Code styling */
  & code {
    font-family: var(--font-mono);
    font-size: var(--font-size-s);
    background: oklch(0% 0 0 / 0.08);
    padding: var(--size-2xs) var(--size-xs);
    border-radius: var(--radius-s);
  }

  & pre {
    margin-block: var(--size-xs);
    padding: var(--size-s);
    border-radius: var(--radius-s);
    background: oklch(0% 0 0 / 0.06);
    overflow-x: auto;

    & code {
      background: transparent;
      padding: 0;
    }
  }
}

/* Typing dots: only while the bubble has no content yet. An empty bubble,
   or one holding just chat-window's visually-hidden typing label, draws the
   dots; as soon as a transport writes content the dots go away, even if it
   forgets to clear data-status. */
chat-message[data-status="typing"] > chat-bubble:is(:empty, :has(> [data-chat-typing]:only-child)) {
  min-width: 3.5rem;
  min-height: 2rem;
  display: flex;
  align-items: center;

  &::after {
    content: '';
    display: inline-block;
    width: 28px;
    height: 8px;
    background:
      radial-gradient(circle, currentColor 2px, transparent 2px)   0px center / 8px 8px no-repeat,
      radial-gradient(circle, currentColor 2px, transparent 2px)  10px center / 8px 8px no-repeat,
      radial-gradient(circle, currentColor 2px, transparent 2px)  20px center / 8px 8px no-repeat;
    animation: vb-typing-dots 1.2s infinite ease-in-out;
    opacity: 0.6;
  }
}

@keyframes vb-typing-dots {
  0%, 100% { opacity: 0.6; transform: translateY(0); }
  16%      { opacity: 1;   transform: translateY(-2px); }
}

@media (prefers-reduced-motion: reduce) {
  chat-message[data-status="typing"] > chat-bubble::after {
    animation: none;
    opacity: 0.4;
  }
}
