/* data-paged: baseline styles for the injected pagination nav.
   Authors override via standard cascade — these set sensible defaults
   so the controls render usable without bespoke styling. */

nav[data-paged-nav] {
  display: flex;
  justify-content: center;
  margin-block: var(--size-s, 0.75rem);

  & > ol {
    display: flex;
    flex-wrap: wrap;
    gap: var(--size-2xs, 0.375rem);
    padding: 0;
    margin: 0;
    list-style: none;
    align-items: center;
  }

  & button {
    min-inline-size: 2rem;
    padding: 0.25rem 0.5rem;
    border: var(--border-width-thin, 1px) solid var(--color-border, #ccc);
    border-radius: var(--radius-s, 0.25rem);
    background: var(--color-surface, #fff);
    color: var(--color-text, #222);
    font: inherit;
    font-size: var(--font-size-s, 0.875rem);
    cursor: var(--cursor-custom-pointer, pointer);
  }

  & button:hover:not([disabled]) {
    background: var(--color-hover-bg, var(--color-surface-raised, #f5f5f5));
    color: var(--color-hover-text, var(--color-text, #222));
  }

  & button[aria-current="page"] {
    background: var(--color-primary, #0066cc);
    color: var(--color-text-on-primary, #fff);
    border-color: var(--color-primary, #0066cc);
  }

  & button[disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  & [data-paged-ellipsis] {
    color: var(--color-text-muted, #666);
    padding-inline: var(--size-2xs, 0.375rem);
  }

  & [data-paged-status] {
    color: var(--color-text-muted, #666);
    font-size: var(--font-size-s, 0.875rem);
    padding-inline: var(--size-s, 0.75rem);
  }

  & button[data-paged-loadmore] {
    /* Load-more is a single full-width-ish action button. */
    min-inline-size: 12rem;
    padding-block: var(--size-xs, 0.5rem);
  }
}

/* Forced colors: the current page is otherwise marked only by its fill,
   which the UA paints out. Re-assert it with system colours plus a
   thicker border so it stays distinct from the other buttons. */
@media (forced-colors: active) {
  nav[data-paged-nav] button[aria-current="page"] {
    forced-color-adjust: none;
    background: Highlight;
    color: HighlightText;
    border: 2px solid CanvasText;
  }

  nav[data-paged-nav] button[disabled] {
    opacity: 1;
    color: GrayText;
    border-color: GrayText;
  }
}
