/* --- Progressive enhancement: no-JS fallback --- */
print-page:not(:defined) {
  display: block;
}

/* print-page: Print button with optional raw-mode toggle */

print-page {
  display: inline-flex;
  align-items: center;
  gap: var(--size-s);
}

print-page .print-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--size-xs);
  padding: var(--size-2xs, 0.25rem);
  min-block-size: 0;
  min-inline-size: 0;
  background: var(--color-surface);
  border: var(--border-width-thin) solid var(--color-border);
  border-radius: var(--radius-m);
  color: var(--color-text);
  cursor: var(--cursor-custom-pointer, pointer);
  transition: background var(--duration-fast), color var(--duration-fast), border-color var(--duration-fast);
}

print-page .print-trigger:hover {
  border-color: var(--color-interactive);
  background: color-mix(in oklab, var(--color-interactive) 8%, transparent);
}

print-page label {
  display: inline-flex;
  align-items: center;
  gap: var(--size-2xs);
  font-size: var(--font-size-s);
  color: var(--color-text-muted);
  cursor: var(--cursor-custom-pointer, pointer);
  user-select: none;
}

/* Never print the print button itself. Lives here (not only in
   utils/print.css) because that rule sits inside html:not([data-print-raw])
   and so did not apply in raw-toggle mode. */
@media print {
  print-page {
    display: none !important;
  }
}
