/**
 * Color Design Tokens
 * OKLCH-based seed-and-derive architecture
 *
 * Themes set hue, lightness, and chroma seeds. Core derives all state
 * variants (hover, active, subtle) so themes never need to redeclare them.
 * Use data-mode="light|dark" to force a specific mode.
 */

/* @property registrations for hue/seed tokens are in src/main.css (top-level) */

:root {
  /* Enable light-dark() function */
  color-scheme: light dark;

  /* ==================== GRAY SCALE ==================== */
  /* Neutral grays (achromatic - zero chroma) */
  --color-gray-50: oklch(98% 0 0);
  --color-gray-100: oklch(96% 0 0);
  --color-gray-200: oklch(90% 0 0);
  --color-gray-300: oklch(80% 0 0);
  --color-gray-400: oklch(70% 0 0);
  --color-gray-500: oklch(55% 0 0);
  --color-gray-600: oklch(45% 0 0);
  --color-gray-700: oklch(35% 0 0);
  --color-gray-800: oklch(25% 0 0);
  --color-gray-900: oklch(15% 0 0);
  --color-gray-950: oklch(10% 0 0);

  /* Pure values */
  --color-white: oklch(100% 0 0);
  --color-black: oklch(0% 0 0);

  /* Open Props compatible aliases (0-9, light to dark) */

  /* ==================== BRAND HUES ==================== */
  /* Default hues (neutral blue) - themes override these */
  --hue-primary: 260;
  --hue-secondary: 200;
  --hue-accent: 30;

  /* ==================== BRAND SEEDS ==================== */
  /* Lightness and chroma seeds — brand themes override these.
     --lightness-primary / --chroma-primary are mode-dependent and live in
     the light-seed rule below (dark values in the dark-mode rule). */
  --lightness-secondary: 50%;
  --chroma-secondary: 0.08;
  --lightness-accent: 65%;
  --chroma-accent: 0.18;
}

/* ==================== LIGHT SEEDS ==================== */
/* One source for the light primary seeds: the page root, and a scoped
   data-mode="light" region inside a dark page (which would otherwise
   inherit the dark seeds from :root[data-mode="dark"]). */
:root,
[data-mode="light"] {
  --lightness-primary: 50%;
  --chroma-primary: 0.2;
}

/* ==================== DERIVED TOKENS ==================== */
/* Everything below is derived from the seeds through var() chains, and a
   custom property's var() references are resolved on the element that
   declares it — so tokens declared only on :root stay frozen at the root's
   values for every descendant. Declaring them on scoped data-mode elements
   too re-derives them from that element's own seeds and surfaces: an
   <aside data-mode="dark"> on a light page gets dark --color-primary,
   --color-hover-bg, etc., and data-mode="light" inside a dark page gets
   the light ones (light-dark() resolves against the element's own
   color-scheme). Concrete dark surfaces come from the dark-mode rule
   further down, which wins on source order.
   :where([data-theme]) does the same for a theme scoped to an element
   (<article data-theme="amber"> on a swiss page): seed-only themes set
   just --hue-* / --lightness-* / --chroma-*, so the element must derive
   its own colours from them. Zero specificity, and this is @layer tokens:
   a theme's own literal --color-* (@layer bundle-theme, or unlayered)
   always wins over these derivations. */
:root,
[data-mode="light"],
[data-mode="dark"],
:where([data-theme]) {
  /* ==================== BRAND COLORS ==================== */
  /* Derived from seeds + hues — themes set seeds, core derives states */
  --color-primary: oklch(var(--lightness-primary) var(--chroma-primary) var(--hue-primary));
  --color-primary-hover: oklch(from var(--color-primary) calc(l - 0.08) calc(c + 0.02) h);
  --color-primary-active: oklch(from var(--color-primary) calc(l - 0.12) c h);
  --color-primary-subtle: oklch(from var(--color-primary) 0.95 0.03 h);

  /* Secondary */
  --color-secondary: oklch(var(--lightness-secondary) var(--chroma-secondary) var(--hue-secondary));
  --color-secondary-hover: oklch(from var(--color-secondary) calc(l - 0.08) c h);
  --color-secondary-subtle: oklch(from var(--color-secondary) 0.95 0.03 h);

  /* Accent */
  --color-accent: oklch(var(--lightness-accent) var(--chroma-accent) var(--hue-accent));
  --color-accent-hover: oklch(from var(--color-accent) calc(l - 0.08) c h);
  --color-accent-subtle: oklch(from var(--color-accent) 0.95 0.03 h);

  /* ==================== STATUS COLORS ==================== */
  --color-success: oklch(55% 0.2 145);
  --color-success-subtle: light-dark(
    oklch(95% 0.05 145),
    oklch(25% 0.08 145)
  );
  --color-success-text: light-dark(
    oklch(35% 0.12 145),
    oklch(75% 0.15 145)
  );

  --color-warning: oklch(70% 0.18 70);
  --color-warning-subtle: light-dark(
    oklch(95% 0.08 70),
    oklch(25% 0.1 70)
  );
  --color-warning-text: light-dark(
    oklch(40% 0.12 70),
    oklch(80% 0.12 70)
  );

  --color-error: oklch(55% 0.22 25);
  --color-error-subtle: light-dark(
    oklch(95% 0.05 25),
    oklch(25% 0.08 25)
  );
  --color-error-text: light-dark(
    oklch(40% 0.15 25),
    oklch(75% 0.18 25)
  );

  --color-info: oklch(55% 0.15 240);
  --color-info-subtle: light-dark(
    oklch(95% 0.05 240),
    oklch(25% 0.08 240)
  );
  --color-info-text: light-dark(
    oklch(35% 0.12 240),
    oklch(75% 0.12 240)
  );

  /* ==================== SEMANTIC COLORS ==================== */
  /* Surface colors (backgrounds) */
  --color-background: light-dark(var(--color-white), var(--color-gray-950));
  --color-surface: light-dark(var(--color-white), var(--color-gray-900));
  --color-surface-raised: light-dark(var(--color-gray-50), var(--color-gray-800));
  --color-surface-sunken: light-dark(var(--color-gray-100), var(--color-gray-950));
  --color-surface-alt: light-dark(var(--color-gray-100), var(--color-gray-800));

  /* Text colors */
  --color-text: light-dark(var(--color-gray-900), var(--color-gray-100));
  --color-text-muted: light-dark(var(--color-gray-600), var(--color-gray-400));
  --color-text-subtle: light-dark(var(--color-gray-500), var(--color-gray-500));
  --color-text-inverted: light-dark(var(--color-white), var(--color-gray-900));
  --color-text-on-primary: var(--color-white);

  /* Border colors */
  --color-border: light-dark(var(--color-gray-200), var(--color-gray-700));
  --color-border-strong: light-dark(var(--color-gray-300), var(--color-gray-600));
  --color-border-subtle: light-dark(var(--color-gray-100), var(--color-gray-800));
  --color-border-muted: light-dark(var(--color-gray-100), var(--color-gray-800));
  --color-border-focus: var(--color-primary);

  /* Scrollbar */
  --scrollbar-thumb: light-dark(var(--color-gray-400), var(--color-gray-600));
  --scrollbar-track: transparent;

  /* Interactive colors (buttons, links) */
  --color-interactive: var(--color-primary);
  --color-interactive-hover: var(--color-primary-hover);
  --color-interactive-active: var(--color-primary-active);

  /* Row stripe — the alternating wash for table[data-striped] and
     dl[data-striped]. A text-tinted mix, so it shows on any surface in
     either mode and stays distinct from the row hover colour. */
  --color-row-stripe: color-mix(in oklch, var(--color-text) 5%, transparent);

  /* Interactive state colors — hover/active for list items, menus, nav links, table rows.
     Themes override these 4 tokens to control all interactive surfaces at once. */
  --color-hover-bg: var(--color-surface-raised);
  --color-hover-text: var(--color-interactive);
  --color-active-bg: transparent;
  --color-active-text: var(--color-interactive);

  /* Overlay colors */
  --color-overlay-subtle: light-dark(
    oklch(0% 0 0 / 0.05),
    oklch(100% 0 0 / 0.05)
  );
  --color-overlay-medium: light-dark(
    oklch(0% 0 0 / 0.15),
    oklch(100% 0 0 / 0.10)
  );
  --color-overlay-strong: light-dark(
    oklch(0% 0 0 / 0.50),
    oklch(0% 0 0 / 0.70)
  );

  /* Focus ring */
  --color-focus-ring: var(--color-primary);
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
  --focus-ring-color: var(--color-focus-ring);
}

/* Auto-contrast tokens — returns black or white for any colored surface.
   Components use these via fallback chain: var(--color-text-on-X-auto, white)
   so browsers without contrast-color() gracefully degrade. */
@supports (color: contrast-color(red)) {
  :root,
  [data-mode="light"],
  [data-mode="dark"],
  :where([data-theme]) {
    --color-text-on-primary-auto:     contrast-color(var(--color-primary));
    --color-text-on-secondary-auto:   contrast-color(var(--color-secondary));
    --color-text-on-accent-auto:      contrast-color(var(--color-accent));
    --color-text-on-interactive-auto:  contrast-color(var(--color-interactive));
    --color-text-on-success-auto:     contrast-color(var(--color-success));
    --color-text-on-warning-auto:     contrast-color(var(--color-warning));
    --color-text-on-error-auto:       contrast-color(var(--color-error));
    --color-text-on-info-auto:        contrast-color(var(--color-info));
  }
}

/* ==================== EXPLICIT MODE OVERRIDES ==================== */
/* Force light mode. Light token values come from the shared rules above
   (light seeds + derived tokens), so a scoped data-mode="light" inside a
   dark page re-declares them from the same source. */
:root[data-mode="light"],
[data-mode="light"] {
  color-scheme: light;
}

/* Force dark mode. The :where() line is a themed element inside a dark
   region (<html data-mode="dark"> … <article data-theme="amber">): the
   derived rule above re-declares its surfaces from light-dark(), so the
   hue-tinted dark surfaces must be re-derived there too, from the
   element's own --hue-primary. Skipped when the element or any ancestor
   is data-mode="light" (same approximation as the accent rules). */
:root[data-mode="dark"],
[data-mode="dark"],
:where([data-mode="dark"] [data-theme]:not([data-mode="light"], [data-mode="light"] [data-theme])) {
  color-scheme: dark;

  /* Brand seeds shift for dark mode contrast */
  --lightness-primary: 65%;
  --chroma-primary: 0.18;

  /* Surface tint chroma — themes can override for stronger/weaker brand tinting */
  --chroma-surface-tint: 0.02;

  /* Hue-tinted dark surfaces (derived from --hue-primary) */
  --color-background: oklch(12% var(--chroma-surface-tint) var(--hue-primary));
  --color-surface: oklch(16% var(--chroma-surface-tint) var(--hue-primary));
  --color-surface-raised: oklch(20% var(--chroma-surface-tint) var(--hue-primary));
  --color-surface-sunken: oklch(10% var(--chroma-surface-tint) var(--hue-primary));

  --color-text: oklch(93% 0.01 var(--hue-primary));
  --color-text-muted: oklch(70% var(--chroma-surface-tint) var(--hue-primary));

  --color-border: oklch(30% var(--chroma-surface-tint) var(--hue-primary));
  --color-border-strong: oklch(50% var(--chroma-surface-tint) var(--hue-primary));

  /* Darker shadows for dark mode */
  --shadow-xs: 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-s: 0 1px 3px oklch(0% 0 0 / 0.4), 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-m: 0 4px 6px oklch(0% 0 0 / 0.4), 0 2px 4px oklch(0% 0 0 / 0.3);
  --shadow-l: 0 10px 15px oklch(0% 0 0 / 0.4), 0 4px 6px oklch(0% 0 0 / 0.3);
  --shadow-xl: 0 20px 25px oklch(0% 0 0 / 0.4), 0 10px 10px oklch(0% 0 0 / 0.3);

  /* No --page-bg-color here: the page follows --color-background in both
     modes (surfaces.css), so a theme's own dark background is what paints. */
}

/* System dark mode with no explicit data-mode (CSS-only / no-JS consumers;
   ThemeManager always writes data-mode when it runs). :root's
   `color-scheme: light dark` already turns every light-dark() token dark,
   so this block only has to supply what light-dark() cannot: the dark
   primary seeds (percentages/numbers, not colours) and the hue-tinted
   surfaces. It MUST stay identical to the [data-mode="dark"] block above —
   tests/components/c-system-dark.spec.js compares the two.
   :not([data-mode="light"]) (not :not([data-mode])) matches the existing
   theme/accent system-dark rules; data-mode="light" keeps forcing light. */
@media (prefers-color-scheme: dark) {
  :root:not([data-mode="light"]),
  :where([data-theme]:not([data-mode="light"], [data-mode="light"] [data-theme])) {
    --lightness-primary: 65%;
    --chroma-primary: 0.18;

    --chroma-surface-tint: 0.02;

    --color-background: oklch(12% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface: oklch(16% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface-raised: oklch(20% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface-sunken: oklch(10% var(--chroma-surface-tint) var(--hue-primary));

    --color-text: oklch(93% 0.01 var(--hue-primary));
    --color-text-muted: oklch(70% var(--chroma-surface-tint) var(--hue-primary));

    --color-border: oklch(30% var(--chroma-surface-tint) var(--hue-primary));
    --color-border-strong: oklch(50% var(--chroma-surface-tint) var(--hue-primary));

    --shadow-xs: 0 1px 2px oklch(0% 0 0 / 0.3);
    --shadow-s: 0 1px 3px oklch(0% 0 0 / 0.4), 0 1px 2px oklch(0% 0 0 / 0.3);
    --shadow-m: 0 4px 6px oklch(0% 0 0 / 0.4), 0 2px 4px oklch(0% 0 0 / 0.3);
    --shadow-l: 0 10px 15px oklch(0% 0 0 / 0.4), 0 4px 6px oklch(0% 0 0 / 0.3);
    --shadow-xl: 0 20px 25px oklch(0% 0 0 / 0.4), 0 10px 10px oklch(0% 0 0 / 0.3);
  }
}

/* ==================== THEME TRANSITIONS ==================== */
/* Smooth interpolation when switching themes (hues + seeds) */
:root {
  transition:
    --hue-primary var(--duration-slow) var(--ease-default),
    --hue-secondary var(--duration-slow) var(--ease-default),
    --hue-accent var(--duration-slow) var(--ease-default),
    --lightness-primary var(--duration-slow) var(--ease-default),
    --chroma-primary var(--duration-slow) var(--ease-default),
    --lightness-secondary var(--duration-slow) var(--ease-default),
    --chroma-secondary var(--duration-slow) var(--ease-default),
    --lightness-accent var(--duration-slow) var(--ease-default),
    --chroma-accent var(--duration-slow) var(--ease-default),
    --chroma-surface-tint var(--duration-slow) var(--ease-default);
}

@media (prefers-reduced-motion: reduce) {
  :root {
    transition: none;
  }
}

:root[data-motion-reduced] {
  transition: none;
}
