/**
 * Accessibility Theme: Large Text
 * Size-focused theme for improved readability and touch accessibility
 *
 * Features:
 * - 25% larger base font size (20px vs 16px default)
 * - 44px minimum touch targets (WCAG 2.5.8 Target Size)
 * - Increased spacing for better visual separation
 * - Improved line height for readability
 *
 * Apply via: data-theme="a11y-large-text"
 * Composable: data-theme="forest a11y-large-text"
 */

@layer bundle-theme {
  :root[data-theme~="a11y-large-text"],
  [data-theme~="a11y-large-text"] {
    /* ===== FONT SIZE SCALE - 25% LARGER ===== */
    /* Base size: 1.25rem (20px) instead of 1rem (16px) */
    --font-size-xs: 0.9375rem;   /* 15px - still readable */
    --font-size-s: 1.0625rem;   /* 17px */
    --font-size-m: 1.25rem;     /* 20px - new base */
    --font-size-l: 1.4375rem;   /* 23px */
    --font-size-xl: 1.5625rem;   /* 25px */
    --font-size-2xl: 1.875rem;   /* 30px */
    --font-size-3xl: 2.375rem;   /* 38px */
    --font-size-4xl: 2.8125rem;  /* 45px */
    --font-size-5xl: 3.75rem;    /* 60px */

    /* ===== LINE HEIGHT - MORE GENEROUS ===== */
    --line-height-tight: 1.35;
    --line-height-snug: 1.5;
    --line-height-normal: 1.7;     /* More breathing room */
    --line-height-relaxed: 1.85;
    --line-height-loose: 2;

    /* ===== TOUCH TARGETS - WCAG 2.5.8 COMPLIANT ===== */
    /* Minimum 44x44px for all interactive elements */
    --size-touch-min: 2.75rem;   /* 44px */

    /* ===== SPACING - INCREASED FOR CLARITY ===== */
    /* 25% larger spacing to match the text scale */
    --size-unit: 0.3125rem;      /* 5px base (vs 4px) */
    --size-3xs: 0.15625rem;      /* 2.5px */
    --size-2xs: 0.3125rem;       /* 5px */
    --size-xs: 0.625rem;         /* 10px */
    --size-s: 0.9375rem;         /* 15px */
    --size-m: 1.25rem;           /* 20px */
    --size-l: 1.875rem;          /* 30px */
    --size-xl: 2.5rem;           /* 40px */
    --size-2xl: 3.75rem;         /* 60px */
    --size-3xl: 5rem;            /* 80px */

    /* Numeric spacing aliases */
    --size-1: 0.3125rem;         /* 5px */
    --size-2: 0.625rem;          /* 10px */
    --size-3: 1.25rem;           /* 20px */
    --size-4: 1.5625rem;         /* 25px */
    --size-5: 1.875rem;          /* 30px */
    --size-6: 2.1875rem;         /* 35px */
    --size-7: 2.5rem;            /* 40px */
    --size-8: 3.75rem;           /* 60px */
    --size-9: 5rem;              /* 80px */
    --size-10: 6.25rem;          /* 100px */

    /* ===== CONTENT WIDTH - ADJUSTED ===== */
    /* Slightly narrower to maintain comfortable line length */
    --content-narrow: 35rem;
    --content-normal: 55rem;
    --content-wide: 75rem;

    /* Measure adjusted for larger text */
    --measure-narrow: 40ch;
    --measure-normal: 60ch;
    --measure-wide: 75ch;

    /* ===== FOCUS INDICATORS ===== */
    /* Larger, more visible focus rings */
    --focus-ring-width: 3px;
    --focus-ring-offset: 3px;

    /* ===== BORDER RADIUS - SLIGHTLY LARGER ===== */
    /* Proportionally larger to match increased sizes */
    --radius-xs: 0.1875rem;      /* 3px */
    --radius-s: 0.375rem;        /* 6px */
    --radius-m: 0.625rem;        /* 10px */
    --radius-l: 1rem;            /* 16px */
    --radius-xl: 1.25rem;        /* 20px */
    --radius-2xl: 1.875rem;      /* 30px */
  }

  /* ===== FLUID COMPOUND: large-text + fluid scaling ===== */
  /* When both a11y-large-text and data-fluid are active, font sizes
     and spacing scale fluidly from the larger base values.
     Type ratio 1.125→1.25, base 1.25rem→1.375rem */
  :root[data-theme~="a11y-large-text"][data-fluid],
  [data-theme~="a11y-large-text"][data-fluid] {
    --size-unit: clamp(0.28rem, 0.0857vi + 0.2629rem, 0.34rem);

    --font-size-xs:  clamp(0.88rem, -0.1538vi + 1.0184rem, 0.9877rem);
    --font-size-s:  clamp(1.1rem, -0.0159vi + 1.1143rem, 1.1111rem);
    --font-size-m:  clamp(1.25rem, 0.1786vi + 1.2143rem, 1.375rem);
    --font-size-l:  clamp(1.4063rem, 0.4464vi + 1.317rem, 1.7188rem);
    --font-size-xl:  clamp(1.582rem, 0.8092vi + 1.4202rem, 2.1484rem);
    --font-size-2xl: clamp(1.7798rem, 1.2939vi + 1.521rem, 2.6855rem);
    --font-size-3xl: clamp(2.0023rem, 1.9353vi + 1.6152rem, 3.3569rem);
    --font-size-4xl: clamp(2.2525rem, 2.7766vi + 1.6972rem, 4.1962rem);
    --font-size-5xl: clamp(2.5341rem, 3.873vi + 1.7595rem, 5.2452rem);
  }
}
