/* layout-cover: Full-height container with vertically centered principal element
 *
 * One rule set for <layout-cover> and [data-layout="cover"]. */

/* xl is 100dvh, not 100vh — dvh accounts for mobile browser chrome, so
   covers stop being cropped on phones. See the spec's rationale. */
:is(layout-cover, [data-layout="cover"]) {
  --_min-height: var(--layout-min, var(--_min-height-token, 100dvh));

  /* Reset variant-only private props so an outer layout's values don't
     inherit into a nested host that set nothing (see layout-grid/styles.css). */
  --_min-height-token: initial;
  --_padding: initial;

  display: flex;
  flex-direction: column;
  min-block-size: var(--_min-height);
  padding: var(--_padding, var(--size-m));

  &[data-layout-min="s"]    { --_min-height-token: 50vh; }
  &[data-layout-min="m"]    { --_min-height-token: 70vh; }
  &[data-layout-min="l"]    { --_min-height-token: 80vh; }
  &[data-layout-min="xl"]   { --_min-height-token: 100dvh; }
  &[data-layout-min="auto"] { --_min-height-token: auto; }

  &[data-layout-padding="none"] { --_padding: 0; }
  &[data-layout-padding="s"]    { --_padding: var(--size-s); }
  &[data-layout-padding="m"]    { --_padding: var(--size-m); }
  &[data-layout-padding="l"]    { --_padding: var(--size-l); }
  &[data-layout-padding="xl"]   { --_padding: var(--size-xl); }

  /* Minimum space between all children; the principal's auto margins
     still centre it in whatever space is left. */
  &[data-layout-gap="none"]  { gap: 0; }
  &[data-layout-gap="3xs"]   { gap: var(--size-3xs); }
  &[data-layout-gap="2xs"]   { gap: var(--size-2xs); }
  &[data-layout-gap="xs"]    { gap: var(--size-xs); }
  &[data-layout-gap="s"]     { gap: var(--size-s); }
  &[data-layout-gap="m"]     { gap: var(--size-m); }
  &[data-layout-gap="l"]     { gap: var(--size-l); }
  &[data-layout-gap="xl"]    { gap: var(--size-xl); }
  &[data-layout-gap="2xl"]   { gap: var(--size-2xl); }
  &[data-layout-gap="3xl"]   { gap: var(--size-3xl); }

  /* The principal (centered) element - use data-layout-principal on the child */
  & > [data-layout-principal] {
    margin-block: auto;
  }

  /* Header element (top-aligned) */
  & > header,
  & > [data-layout-cover-top] {
    margin-block-end: auto;
  }

  /* Footer element (bottom-aligned) */
  & > footer,
  & > [data-layout-cover-bottom] {
    margin-block-start: auto;
  }

  /* Single child auto-centers (the element fork lacked this) */
  & > :only-child {
    margin-block: auto;
  }

  &[data-layout-centered] {
    align-items: center;
    text-align: center;

    /* Pinned edges keep the full inline size: shrink-wrapping a header
       made inner layouts (a justify="between" brand/nav row) collapse to
       content width. Only the principal and other children centre. */
    & > :is(header, footer, [data-layout-cover-top], [data-layout-cover-bottom]) {
      align-self: stretch;
    }
  }
}
