/* tooltip: Native tooltip using Popover API + CSS Anchor Positioning */

/*
 * Usage:
 * <button aria-describedby="tip1">Hover me</button>
 * <div id="tip1" popover="hint" role="tooltip">Tooltip content</div>
 *
 * For click-triggered (no JS needed where anchor positioning is
 * supported: the invoker is the popover's implicit anchor):
 * <button popovertarget="tip2">Click me</button>
 * <div id="tip2" popover="auto" role="tooltip">Click tooltip</div>
 */

/* --- Interest timing ---
   Native interest invokers and VB's polyfill (utils/interest-polyfill.js)
   both read the delays from the INVOKER, not the popover, so VB's
   tooltip timing sits on [interestfor]. The standard properties are for
   native support (Chrome 142+); the custom properties are what the
   polyfill reads where they are not. Set as shorthands so an author's
   shorthand or longhand (the polyfill reads its longhands first) both
   override them. Override both on the invoker:
   [interestfor] { interest-delay: 0s 300ms; --interest-delay: 0s 300ms } */
[interestfor] {
  interest-delay: 200ms 100ms;
  --interest-delay: 200ms 100ms;
}

[role="tooltip"][popover] {
  /* Reset popover defaults */
  border: none;
  padding: 0;
  margin: 0;
  background: transparent;
  overflow: visible;

  /* Tooltip styling */
  background: var(--color-text);
  color: var(--color-text-inverted);
  padding: var(--size-xs) var(--size-s);
  font-size: var(--font-size-s);
  line-height: var(--line-height-normal);
  border-radius: var(--radius-s);
  max-inline-size: 20rem;
  white-space: normal;
  word-wrap: break-word;

  /* Animation - exit state */
  opacity: 0;
  transform: translateY(4px);

  transition:
    opacity var(--duration-fast) var(--ease-default),
    transform var(--duration-fast) var(--ease-default),
    display var(--duration-fast) allow-discrete,
    overlay var(--duration-fast) allow-discrete;
}

[role="tooltip"][popover]:popover-open {
  opacity: 1;
  transform: translateY(0);
}

/* Entry animation starting point */
@starting-style {
  [role="tooltip"][popover]:popover-open {
    opacity: 0;
    transform: translateY(4px);
  }
}

/* --- Positioning --- */

[role="tooltip"][popover] {
  position: fixed;
  /* JS sets top/left, or CSS anchor positioning takes over */
}

/* Anchor-positioned tooltips (init-created, outside tool-tip) */
[role="tooltip"][popover][data-anchor] {
  inset: auto;
}

/* Anything else (a click tooltip opened by popovertarget, an authored
   interestfor tip) anchors to its invoker: a popover shown by an invoker
   has it as its implicit anchor, and the interest polyfill writes an
   inline position-anchor (which wins over auto). position-anchor: auto is
   set explicitly because Chromium 144-150 made the initial value none.
   tool-tip's pop-over (data-anchor-name) places itself. Without anchor
   positioning, tooltip-init.js positions click tooltips with top/left. */
@supports (anchor-name: --x) {
  [role="tooltip"][popover]:not([data-anchor], [data-anchor-name]) {
    position-anchor: auto;
    inset: auto;
  }
}

/* anchor() and the centring translate only make sense with anchor
   positioning. Unguarded, the translate still applied on the JS
   fallback path (pixel insets) and shifted the tip twice; tool-tip
   worked around it with an inline translate:none. inset:auto stays
   outside the guard so the UA popover inset:0 never fights the
   fallback's pixel insets. */
@supports (anchor-name: --x) {
  [role="tooltip"][popover]:not([data-anchor-name]):not([data-tooltip-position]),
  [role="tooltip"][popover]:not([data-anchor-name])[data-tooltip-position="top"] {
    bottom: anchor(top);
    left: anchor(center);
    translate: -50% calc(-1 * var(--size-xs));
  }

  [role="tooltip"][popover]:not([data-anchor-name])[data-tooltip-position="bottom"] {
    top: anchor(bottom);
    left: anchor(center);
    translate: -50% var(--size-xs);
  }

  [role="tooltip"][popover]:not([data-anchor-name])[data-tooltip-position="left"] {
    right: anchor(left);
    top: anchor(center);
    translate: calc(-1 * var(--size-xs)) -50%;
  }

  [role="tooltip"][popover]:not([data-anchor-name])[data-tooltip-position="right"] {
    left: anchor(right);
    top: anchor(center);
    translate: var(--size-xs) -50%;
  }
}

/* --- Arrow (optional) --- */

[role="tooltip"][popover] > .tooltip-arrow {
  position: absolute;
  inline-size: 8px;
  block-size: 8px;
  background: inherit;
  transform: rotate(45deg);
  pointer-events: none;
}

/* Arrow positions */
[role="tooltip"][popover]:not([data-tooltip-position]),
[role="tooltip"][popover][data-tooltip-position="top"] {
  & > .tooltip-arrow {
    inset-block-end: -4px;
    inset-inline-start: calc(50% - 4px);
  }
}

[role="tooltip"][popover][data-tooltip-position="bottom"] > .tooltip-arrow {
  inset-block-start: -4px;
  inset-inline-start: calc(50% - 4px);
}

/* left/right are physical sides (the tip sits physically left/right of
   the trigger in any direction), so the arrow uses physical insets to
   keep pointing at the trigger in RTL. */
[role="tooltip"][popover][data-tooltip-position="left"] > .tooltip-arrow {
  right: -4px;
  inset-block-start: calc(50% - 4px);
}

[role="tooltip"][popover][data-tooltip-position="right"] > .tooltip-arrow {
  left: -4px;
  inset-block-start: calc(50% - 4px);
}

/* --- Content inside tooltips --- */

/* Plain hints share the inverted surface, so they share the overlays. */
:is([role="tooltip"][popover], [popover="hint"]) {
  /* The tooltip surface is always dark (in light mode) / always light
     (in dark mode) regardless of theme, so kbd / code overlays can't
     use the light-dark() overlay tokens — those flip with the page mode,
     not the tooltip mode. Use translucent currentColor instead so the
     overlay is always a few steps off from whatever color the tooltip
     text sits at. */
  & kbd {
    background: color-mix(in oklab, currentColor 18%, transparent);
    border-color: color-mix(in oklab, currentColor 35%, transparent);
    box-shadow: 0 1px 0 color-mix(in oklab, currentColor 12%, transparent);
    color: inherit;
  }

  /* small text */
  & small {
    opacity: 0.8;
  }

  /* code styling */
  & code {
    background: color-mix(in oklab, currentColor 18%, transparent);
    color: inherit;
  }
}

/* --- Dark Mode --- */

/* Dark mode handled automatically via light-dark() semantic tokens */

/* ---- interestfor-driven tooltips ---- */

[popover="hint"]:not([role="tooltip"]) {
  border: none;
  padding: 0;
  margin: 0;
  overflow: visible;

  background: var(--color-text);
  color: var(--color-text-inverted);
  padding: var(--size-xs) var(--size-s);
  font-size: var(--font-size-s);
  border-radius: var(--radius-s);
  max-inline-size: 20rem;
  white-space: normal;
  word-wrap: break-word;

  /* Positioning — fixed for JS fallback, anchor for native path */
  position: fixed;
  inset: unset;
  position-area: block-start;
  margin-block-end: 8px;
  position-try-fallbacks: flip-block;

  /* Animation */
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity var(--duration-fast) var(--ease-default),
    transform var(--duration-fast) var(--ease-default),
    display var(--duration-fast) allow-discrete,
    overlay var(--duration-fast) allow-discrete;
}

[popover="hint"]:not([role="tooltip"]):popover-open {
  opacity: 1;
  transform: translateY(0);
}

@starting-style {
  [popover="hint"]:not([role="tooltip"]):popover-open {
    opacity: 0;
    transform: translateY(4px);
  }
}

/* Dark mode handled automatically via light-dark() semantic tokens */

/* --- Forced Colors --- */

@media (forced-colors: active) {
  [role="tooltip"][popover],
  [popover="hint"]:not([role="tooltip"]) {
    border: 1px solid CanvasText;
  }

  [role="tooltip"][popover] > .tooltip-arrow {
    background: CanvasText;
  }
}

/* --- Reduced Motion --- */

@media (prefers-reduced-motion: reduce) {
  [role="tooltip"][popover] {
    transition: none;
  }

  [popover="hint"]:not([role="tooltip"]) {
    transition: none;
  }
}
