/* --- Progressive enhancement: no-JS fallback --- */
settings-panel:not(:defined) {
  display: none;
}

/* settings-panel: Compact settings panel */

settings-panel {
  display: inline-block;
  position: relative;

  &[open] .settings-panel {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    /* visibility flips at once (0s) so open() can move focus into the panel */
    transition:
      opacity var(--motion-enter-duration, 200ms) var(--ease-out, ease-out),
      visibility 0s,
      transform var(--motion-enter-duration, 200ms) var(--ease-out, ease-out);
  }
}

@scope (settings-panel) {
  /* --- Trigger button (FAB — matches back-to-top) --- */
  .settings-trigger {
    all: unset;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: var(--cursor-custom-pointer, pointer);

    /* FAB sizing and shape */
    width: 2.75rem;
    height: 2.75rem;
    border-radius: var(--radius-full, 50%);

    /* Frosted glass appearance */
    background: oklch(from var(--color-text) l c h / 0.08);
    color: var(--color-text);
    border: var(--border-width-thin, 1px) solid var(--color-border);
    box-shadow: var(--shadow-m);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);

    transition: background var(--duration-fast, 150ms), border-color var(--duration-fast, 150ms);

    &:hover {
      background: oklch(from var(--color-text) l c h / 0.15);
      border-color: oklch(from var(--color-text) l c h / 0.25);
    }

    &:focus-visible {
      outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, var(--color-interactive));
      outline-offset: var(--focus-ring-offset, 2px);
    }
  }

  /* --- Panel --- */
  .settings-panel {
    position: absolute;
    inset-block-end: calc(100% + 8px);
    inset-inline-end: 0;
    z-index: 1000;

    inline-size: 320px;
    max-block-size: min(80vh, 500px);
    overflow-y: auto;

    background: var(--color-surface-overlay);
    border: var(--border-width-thin, 1px) solid var(--color-border);
    border-radius: var(--radius-m);
    box-shadow: var(--shadow-m);

    opacity: 0;
    visibility: hidden;
    transform: translateY(0.5rem);
    transition:
      opacity var(--motion-exit-duration, 150ms) var(--ease-out, ease-out),
      visibility var(--motion-exit-duration, 150ms) var(--ease-out, ease-out),
      transform var(--motion-exit-duration, 150ms) var(--ease-out, ease-out);
  }

  /* open() focuses the panel container (tabindex=-1) so screen readers
     announce the dialog; it is not a control, so it draws no focus ring.
     Tab then reaches the close button and the sections. */
  .settings-panel:focus {
    outline: none;
  }

  /* --- Header --- */
  .settings-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--size-xs) var(--size-s) var(--size-xs) var(--size-m);
    border-block-end: var(--border-width-thin, 1px) solid var(--color-border);
    font-size: var(--font-size-s);
    color: var(--color-text-muted);
  }

  .settings-close {
    all: unset;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    border-radius: var(--radius-s);
    cursor: var(--cursor-custom-pointer, pointer);
    color: var(--color-text-muted);
    transition:
      color var(--duration-fast, 150ms),
      background var(--duration-fast, 150ms);

    &:hover {
      color: var(--color-text);
      background: var(--color-hover-bg);
    }

    &:focus-visible {
      outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, var(--color-interactive));
      outline-offset: var(--focus-ring-offset, 2px);
    }
  }

  /* --- Body --- */
  .settings-body {
    padding: 0;
  }

  /* --- Details sections --- */
  .settings-body > details {
    border: none;
    border-radius: 0;
    border-block-end: var(--border-width-thin, 1px) solid var(--color-border);

    &:last-of-type {
      border-block-end: none;
    }

    & > summary {
      padding: var(--size-xs) var(--size-m);
      font-size: var(--font-size-s);
      font-weight: var(--font-weight-medium, 500);
      cursor: var(--cursor-custom-pointer, pointer);
      list-style: none;
      display: flex;
      align-items: center;
      justify-content: space-between;
      color: var(--color-text);
      transition: background var(--duration-fast, 150ms);

      &:hover {
        background: var(--color-hover-bg);
      }

      &::after {
        content: "";
        display: block;
        inline-size: 0.4em;
        block-size: 0.4em;
        /* Physical corner + fixed rotations; RTL flips below. */
        border-right: 2px solid var(--color-text-muted);
        border-bottom: 2px solid var(--color-text-muted);
        transform: rotate(-45deg);
        transition: transform var(--duration-fast, 150ms);
        flex-shrink: 0;
        margin-inline-start: var(--size-s);
      }

      &:dir(rtl)::after {
        transform: rotate(135deg);
      }

      &::-webkit-details-marker { display: none; }
      &::marker { display: none; content: ""; }
    }

    &[open] > summary::after {
      transform: rotate(45deg);
    }
  }

  /* --- Section content --- */
  .settings-section {
    padding: 0 var(--size-m) var(--size-s);
    display: flex;
    flex-direction: column;
    gap: var(--size-s);
  }

  .settings-label {
    font-size: var(--font-size-xs, 0.75rem);
    font-weight: var(--font-weight-medium, 500);
    color: var(--color-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Segmented controls use the public [data-segmented] pattern */

  /* --- Select --- */
  select {
    font: inherit;
    font-size: var(--font-size-s);
    padding: var(--size-xs) var(--size-s);
    border: var(--border-width-thin, 1px) solid var(--color-border);
    border-radius: var(--radius-s);
    background-color: var(--color-surface);
    color: var(--color-text);
    cursor: var(--cursor-custom-pointer, pointer);
    inline-size: 100%;

    &:focus-visible {
      outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, var(--color-interactive));
      outline-offset: var(--focus-ring-offset, 2px);
    }
  }

  /* --- Toggle rows --- */
  .toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--size-s);
    font-size: var(--font-size-s);
    cursor: var(--cursor-custom-pointer, pointer);
    padding: var(--size-2xs, 4px) 0;
  }

  /* --- Density row (visible when fluid is on) --- */
  .density-row {
    display: flex;
    flex-direction: column;
    gap: var(--size-xs);

    &[hidden] {
      display: none;
    }
  }

  /* --- System info section --- */
  .system-info {
    font-size: var(--font-size-xs, 0.75rem);
    color: var(--color-text-muted);
  }

  .system-version {
    margin: 0;
  }

  .system-version code {
    font-family: var(--font-mono, monospace);
    font-size: inherit;
  }

  .system-sw-status {
    margin: 0;
  }

  .system-actions {
    display: flex;
    gap: var(--size-xs);
    padding: 0;
    border: none;
  }

  .system-actions button {
    all: unset;
    font-size: var(--font-size-xs, 0.75rem);
    padding: var(--size-2xs, 4px) var(--size-xs, 8px);
    border: var(--border-width-thin, 1px) solid var(--color-border);
    border-radius: var(--radius-s);
    cursor: var(--cursor-custom-pointer, pointer);
    color: var(--color-text-muted);
    transition:
      color var(--duration-fast, 150ms),
      border-color var(--duration-fast, 150ms);

    &:hover {
      color: var(--color-text);
      border-color: var(--color-text-muted);
    }

    &:focus-visible {
      outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, var(--color-interactive));
      outline-offset: var(--focus-ring-offset, 2px);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  /* --- Footer --- */
  .settings-footer {
    padding: var(--size-xs) var(--size-m);
    border-block-start: var(--border-width-thin, 1px) solid var(--color-border);
  }

  .settings-reset[hidden] {
    display: none;
  }

  /* In-panel reset confirmation (replaces window.confirm) */
  .settings-reset-confirm {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: var(--size-xs);
    margin: 0;
    font-size: var(--font-size-xs);
    color: var(--color-text);

    &[hidden] {
      display: none;
    }

    & > span {
      flex-basis: 100%;
      text-align: center;
    }

    & button {
      font: inherit;
      padding: var(--size-2xs, 4px) var(--size-s);
    }
  }

  .settings-reset {
    all: unset;
    display: block;
    inline-size: 100%;
    text-align: center;
    padding: var(--size-2xs) var(--size-s);
    font-size: var(--font-size-xs);
    color: var(--color-text-muted);
    cursor: var(--cursor-custom-pointer, pointer);
    transition: color var(--duration-fast, 150ms);

    &:hover {
      color: var(--color-text);
    }

    &:focus-visible {
      outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, var(--color-interactive));
      outline-offset: var(--focus-ring-offset, 2px);
    }
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  @scope (settings-panel) {
    .settings-panel {
      transition: none;
      transform: none;
    }
  }
}
