/* context-menu: composes <pop-over data-mode="auto"> as the menu
   surface. The pop-over receives inline top/left from JS at the cursor
   position. pop-over owns the popover attribute, light-dismiss, and
   the display:none cascade re-assertion. */

context-menu:not(:defined) {
  display: none;
}

context-menu {
  display: contents;
}

/* --- Menu list inside the pop-over surface ----------------------- */

@scope (context-menu) {
  /* The menu is a passthrough inside pop-over — strip its own chrome
     so the pop-over's surface treatment shows through. */
  menu,
  ul[role="menu"] {
    display: flex;
    flex-direction: column;
    flex-wrap: nowrap;
    gap: 0;
    margin: 0;
    padding: 0;
    list-style: none;
    background: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    min-inline-size: 10rem;

    /* Items */
    & li {
      margin: 0;
      padding: 0;
    }

    /* Group wrapper built by logic.js (<li role="group"><ul role="none">)
       so role="group" contains the items it labels. Lays out exactly like
       the flat authored list. */
    & > li[data-ctx-group] > ul {
      display: flex;
      flex-direction: column;
      gap: 0;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    /* Menu items are plain rows, never themed buttons. Themes live in
       @layer bundle-theme, above this layer by contract, and most of them
       give <button>/<a> borders, shadows, radii or hover transforms — so the
       reset has to be !important (an important declaration in a lower layer
       beats the theme, important or not). This used to be an inline style
       written by logic.js. */
    & li > :is(button, a),
    & [role="menuitem"] {
      border: none !important;
      box-shadow: none !important;
      transform: none !important;
      border-radius: 0 !important;
    }

    & li > button,
    & li > a {
      all: unset;
      display: flex;
      align-items: center;
      justify-content: flex-start;
      gap: var(--size-s);
      inline-size: 100%;
      box-sizing: border-box;
      padding: var(--size-xs) var(--size-m);
      background: transparent;
      color: var(--color-text);
      font: inherit;
      font-size: var(--font-size-s);
      text-align: start;
      text-decoration: none;
      cursor: var(--cursor-custom-pointer, pointer);
      transition: background-color var(--duration-fast) var(--ease-default);

      &:hover,
      &:focus {
        background: var(--color-hover-bg);
        outline: none;
        transform: none;
        box-shadow: none;
      }

      /* Keyboard focus needs more than a tint: draw the focus ring inside
         the row (the surface clips overflow). Important for the same
         reason as the reset above — themes style button:focus-visible. */
      &:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, var(--color-focus-ring)) !important;
        outline-offset: calc(-1 * var(--focus-ring-width, 2px)) !important;
      }

      &:is([data-disabled], [aria-disabled="true"], :disabled) {
        color: var(--color-text-muted);
        cursor: not-allowed;

        &:hover,
        &:focus {
          background: transparent;
        }
      }

      &.danger:not([aria-disabled="true"], :disabled) {
        color: var(--color-error);

        &:hover,
        &:focus {
          background: oklch(from var(--color-error) l c h / 0.1);
        }
      }
    }

    /* Icon support */
    & button > svg,
    & button > icon-wc,
    & a > svg,
    & a > icon-wc {
      flex-shrink: 0;
      inline-size: 1em;
      block-size: 1em;
    }

    /* Separator */
    & [role="separator"] {
      block-size: 1px;
      margin: var(--size-2xs) 0;
      background: var(--color-border);
    }

    /* Group label */
    & li[data-group] {
      padding: var(--size-xs) var(--size-m) var(--size-xs) var(--size-s);
      font-size: var(--font-size-xs, 0.75rem);
      font-weight: 600;
      color: var(--color-text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    /* Non-first groups get a top border (on the wrapper once upgraded;
       the bare label before upgrade). */
    & > li[data-group]:not(:first-child),
    & > li[data-ctx-group]:not(:first-child) {
      margin-block-start: var(--size-2xs);
      border-block-start: 1px solid var(--color-border);
    }

    & > li[data-group]:not(:first-child),
    & > li[data-ctx-group]:not(:first-child) li[data-group] {
      padding-block-start: var(--size-s);
    }

    /* Shortcut badge */
    & .ctx-kbd {
      margin-inline-start: auto;
      font-size: var(--font-size-xs, 0.75rem);
      color: var(--color-text-muted);
      background: var(--color-surface-raised);
      padding: var(--size-3xs) var(--size-xs);
      border-radius: var(--radius-s);
      border: var(--border-width-thin) solid var(--color-border);
      font-family: inherit;
    }
  }
}

/* --- Composed pop-over surface ----------------------------------- */

/* Override pop-over's default chrome: context menu uses an overlay
   surface, tight padding, and inline top/left from JS instead of
   anchor-based positioning. */
context-menu > pop-over[data-context-menu-host] {
  /* Cursor-positioned via inline style; cancel pop-over's auto/anchor
     defaults so our inline coords win. */
  position: fixed;
  inset: auto;
  margin: 0;

  padding: var(--size-2xs) 0;
  background: var(--color-surface-overlay);
  border: var(--border-width-thin) solid var(--color-border);
  border-radius: var(--radius-m);
  box-shadow: var(--shadow-m, 0 4px 6px oklch(0% 0 0 / 0.3));
  inline-size: max-content;
  max-inline-size: none;
  overflow: hidden;

  /* Entry animation — scale + fade. */
  opacity: 0;
  transform: scale(0.95);
  transform-origin: top left;
  transition:
    opacity var(--motion-exit-duration) var(--ease-out),
    transform var(--motion-exit-duration) var(--ease-out),
    display var(--motion-exit-duration) allow-discrete,
    overlay var(--motion-exit-duration) allow-discrete;
}

context-menu > pop-over[data-context-menu-host]:popover-open {
  opacity: 1;
  transform: scale(1);
  transition:
    opacity var(--motion-enter-duration) var(--ease-out),
    transform var(--motion-enter-duration) var(--ease-out),
    display var(--motion-enter-duration) allow-discrete,
    overlay var(--motion-enter-duration) allow-discrete;
}

@starting-style {
  context-menu > pop-over[data-context-menu-host]:popover-open {
    opacity: 0;
    transform: scale(0.95);
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  context-menu > pop-over[data-context-menu-host],
  context-menu > pop-over[data-context-menu-host]:popover-open {
    transition: none;
    transform: none;
  }
}
