/*
 * Token Fallback Contract
 *
 * Every token defined in these files is a guaranteed fallback.
 * Theme bundles (in bundle-theme layer) override these values —
 * they must never introduce new tokens not defined here.
 *
 * A component rendered with only these base tokens must be
 * visually acceptable: readable, usable, not broken.
 * It does not need to be beautiful or on-brand.
 *
 * Rules:
 * 1. All tokens have sensible defaults — no token may be undefined.
 * 2. Themes override existing tokens only — new theme-specific tokens
 *    are a contract violation.
 * 3. Themes must not change layout, spacing structure, or display.
 * 4. Components must use var(--token) references — no hardcoded values.
 */
@import "./spacing.css";
@import "./typography.css";
@import "./characters.css";
@import "./colors.css";
@import "./color-mix.css";
@import "./sizing.css";
@import "./z-index.css";
@import "./breakpoints.css";
@import "./borders.css";
@import "./forms.css";
@import "./shadows.css";
@import "./motion.css";
@import "./fluid.css";
@import "./backdrop.css";
@import "./pointer.css";
@import "./safe-area.css";
@import "./extensions/index.css";

