/**
 * Brand Theme: Minimal
 * A clean, understated design with flat surfaces and subtle interactions
 *
 * Character: Refined, professional, content-focused
 * - Neutral gray primary for understated elegance
 * - Sharp/minimal border radii for clean lines
 * - Flat or very subtle shadows
 * - Subtle, quick animations that don't distract
 */

@layer bundle-theme {
  :root[data-theme~="minimal"],
  [data-theme~="minimal"] {
    /* ===== COLORS ===== */
    /* Neutral palette - relies on typography and spacing for hierarchy */
    --hue-primary: 240;
    --hue-secondary: 240;
    --hue-accent: 210;

    /* Desaturated, sophisticated colors via seeds */
    --lightness-primary: 35%;
    --chroma-primary: 0.03;
    --lightness-secondary: 50%;
    --chroma-secondary: 0.02;
    --lightness-accent: 50%;
    --chroma-accent: 0.08;

    /* Non-standard: dark primary lightens on hover instead of darkening */
    --color-primary-hover: oklch(from var(--color-primary) calc(l + 0.08) c h);
    --color-primary-active: oklch(from var(--color-primary) calc(l + 0.12) c h);
    --color-primary-subtle: oklch(from var(--color-primary) 0.97 0.01 h);

    --color-secondary-hover: oklch(from var(--color-secondary) calc(l - 0.06) c h);

    /* Accent uses a hint of blue for links and interactions */
    --color-accent-hover: oklch(from var(--color-accent) calc(l - 0.06) c h);

    /* ===== TYPOGRAPHY ===== */
    /* System fonts - lets content speak for itself */
    --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

    /* Generous line heights for readability */
    --line-height-normal: 1.6;
    --line-height-relaxed: 1.75;

    /* Subtle letter spacing adjustments */
    --letter-spacing-normal: 0.01em;

    /* ===== SHAPE ===== */
    /* Sharp/minimal radii for clean, precise feel */
    --radius-xs: 0;
    --radius-s: 0.125rem;
    --radius-m: 0.25rem;
    --radius-l: 0.375rem;
    --radius-xl: 0.5rem;
    --radius-2xl: 0.75rem;
    --radius-full: 9999px;

    /* ===== BORDERS ===== */
    /* Thin, subtle borders */
    --border-width-thin: 1px;
    --border-width-medium: 1px;

    /* ===== SHADOWS ===== */
    /* Very subtle or no shadows - flat design */
    --shadow-xs: none;
    --shadow-s: 0 1px 2px 0 oklch(0% 0 0 / 0.03);
    --shadow-m: 0 2px 4px 0 oklch(0% 0 0 / 0.04);
    --shadow-l: 0 4px 8px 0 oklch(0% 0 0 / 0.05);
    --shadow-xl: 0 8px 16px 0 oklch(0% 0 0 / 0.06);
    --shadow-2xl: 0 12px 24px 0 oklch(0% 0 0 / 0.08);

    /* ===== MOTION ===== */
    /* Quick, subtle transitions that don't call attention */
    --duration-instant: 0ms;
    --duration-fast: 75ms;
    --duration-normal: 120ms;
    --duration-slow: 200ms;
    --duration-slower: 300ms;

    /* Linear-ish easing for understated feel */
    --ease-default: cubic-bezier(0.25, 0.1, 0.25, 1);
    --ease-out: cubic-bezier(0.25, 0.1, 0.25, 1);
  }

  /* Minimal + Dark mode */
  :root[data-theme~="minimal"][data-mode="dark"],
  [data-theme~="minimal"][data-mode="dark"],
  [data-mode="dark"] [data-theme~="minimal"]:where(:not([data-mode], [data-mode="light"] [data-theme~="minimal"])) {
    /* Lighter primary for dark mode - still understated */
    --lightness-primary: 70%;
    --chroma-primary: 0.02;

    /* No surface tinting — pure untinted darks */
    --chroma-surface-tint: 0;

    /* Custom surface lightness (differs from core defaults) */
    --color-background: oklch(8% 0 0);
    --color-surface: oklch(12% 0 0);
    --color-surface-raised: oklch(16% 0 0);
    --color-surface-sunken: oklch(6% 0 0);
    --color-surface-alt: oklch(14% 0 0);
    --color-text: oklch(92% 0 0);
    --color-text-muted: oklch(68% 0 0);
    --color-border: oklch(25% 0 0);
    --color-border-strong: oklch(45% 0 0);
    --color-border-muted: oklch(20% 0 0);

    /* Slightly more visible shadows in dark mode */
    --shadow-s: 0 1px 2px 0 oklch(0% 0 0 / 0.1);
    --shadow-m: 0 2px 4px 0 oklch(0% 0 0 / 0.2);
    --shadow-l: 0 4px 8px 0 oklch(0% 0 0 / 0.25);
    --shadow-xl: 0 8px 16px 0 oklch(0% 0 0 / 0.3);
    --shadow-2xl: 0 12px 24px 0 oklch(0% 0 0 / 0.4);
  }

  /* System dark with no data-mode (CSS-only consumers): mirror the dark block. */
  @media (prefers-color-scheme: dark) {
    :root[data-theme~="minimal"]:not([data-mode="light"]),
    [data-theme~="minimal"]:not([data-mode="light"]):where(:not([data-mode="light"] *)) {
      /* Lighter primary for dark mode - still understated */
      --lightness-primary: 70%;
      --chroma-primary: 0.02;

      /* No surface tinting — pure untinted darks */
      --chroma-surface-tint: 0;

      /* Custom surface lightness (differs from core defaults) */
      --color-background: oklch(8% 0 0);
      --color-surface: oklch(12% 0 0);
      --color-surface-raised: oklch(16% 0 0);
      --color-surface-sunken: oklch(6% 0 0);
      --color-surface-alt: oklch(14% 0 0);
      --color-text: oklch(92% 0 0);
      --color-text-muted: oklch(68% 0 0);
      --color-border: oklch(25% 0 0);
      --color-border-strong: oklch(45% 0 0);
      --color-border-muted: oklch(20% 0 0);

      /* Slightly more visible shadows in dark mode */
      --shadow-s: 0 1px 2px 0 oklch(0% 0 0 / 0.1);
      --shadow-m: 0 2px 4px 0 oklch(0% 0 0 / 0.2);
      --shadow-l: 0 4px 8px 0 oklch(0% 0 0 / 0.25);
      --shadow-xl: 0 8px 16px 0 oklch(0% 0 0 / 0.3);
      --shadow-2xl: 0 12px 24px 0 oklch(0% 0 0 / 0.4);
    }
  }
}
