/**
 * Brand Theme: Classic
 * A traditional, sophisticated design with serif typography and subtle elegance
 *
 * Character: Timeless, trustworthy, editorial
 * - Deep blue primary for professionalism and trust
 * - Small, consistent border radii
 * - Subtle shadows for gentle depth
 * - Smooth, graceful animations
 */

@layer bundle-theme {
  :root[data-theme~="classic"],
  [data-theme~="classic"] {
    /* ===== COLORS ===== */
    /* Traditional, trustworthy palette */
    --hue-primary: 220;
    --hue-secondary: 200;
    --hue-accent: 35;

    /* Deep, rich colors via seeds */
    --lightness-primary: 40%;
    --chroma-primary: 0.12;
    --lightness-secondary: 45%;
    --chroma-secondary: 0.08;
    --lightness-accent: 60%;
    --chroma-accent: 0.14;

    /* Non-standard: dark primary lightens on hover instead of darkening */
    --color-primary-hover: oklch(from var(--color-primary) calc(l + 0.08) calc(c + 0.02) h);
    --color-primary-active: oklch(from var(--color-primary) calc(l + 0.12) c h);
    --color-primary-subtle: oklch(from var(--color-primary) 0.96 0.03 h);

    --color-secondary-hover: oklch(from var(--color-secondary) calc(l - 0.06) c h);

    /* Warm gold accent */
    --color-accent-hover: oklch(from var(--color-accent) calc(l - 0.06) c h);

    /* ===== TYPOGRAPHY ===== */
    /* Serif for headings and body - editorial feel */
    --font-sans: Charter, "Bitstream Charter", "Sitka Text", Cambria, Georgia, serif;
    --font-serif: Charter, "Bitstream Charter", "Sitka Text", Cambria, Georgia, serif;

    /* Generous line heights for comfortable reading */
    --line-height-tight: 1.3;
    --line-height-normal: 1.65;
    --line-height-relaxed: 1.8;

    /* Slightly looser letter spacing for elegance */
    --letter-spacing-normal: 0.01em;
    --letter-spacing-wide: 0.05em;

    /* ===== SHAPE ===== */
    /* Small, subtle radii - not too sharp, not too soft */
    --radius-xs: 0.125rem;
    --radius-s: 0.1875rem;
    --radius-m: 0.25rem;
    --radius-l: 0.375rem;
    --radius-xl: 0.5rem;
    --radius-2xl: 0.75rem;

    /* ===== BORDERS ===== */
    /* Slightly thicker borders for classic weight */
    --border-width-thin: 1px;
    --border-width-medium: 2px;

    /* ===== SHADOWS ===== */
    /* Subtle, gentle shadows - not too aggressive */
    --shadow-xs: 0 1px 2px 0 oklch(0% 0 0 / 0.04);
    --shadow-s: 0 1px 3px 0 oklch(0% 0 0 / 0.06),
                 0 1px 2px -1px oklch(0% 0 0 / 0.04);
    --shadow-m: 0 3px 6px -1px oklch(0% 0 0 / 0.07),
                 0 2px 4px -2px oklch(0% 0 0 / 0.05);
    --shadow-l: 0 8px 12px -2px oklch(0% 0 0 / 0.08),
                 0 4px 6px -3px oklch(0% 0 0 / 0.05);
    --shadow-xl: 0 16px 20px -4px oklch(0% 0 0 / 0.09),
                 0 8px 10px -5px oklch(0% 0 0 / 0.05);
    --shadow-2xl: 0 24px 40px -8px oklch(0% 0 0 / 0.12);

    /* ===== MOTION ===== */
    /* Smooth, graceful transitions */
    --duration-instant: 50ms;
    --duration-fast: 120ms;
    --duration-normal: 250ms;
    --duration-slow: 400ms;
    --duration-slower: 600ms;

    /* Smooth, elegant easing */
    --ease-default: cubic-bezier(0.4, 0, 0.2, 1);
    --ease-out: cubic-bezier(0.2, 0, 0.4, 1);
    --ease-in: cubic-bezier(0.4, 0, 0.8, 1);
  }

  /* Classic + Dark mode */
  :root[data-theme~="classic"][data-mode="dark"],
  [data-theme~="classic"][data-mode="dark"],
  [data-mode="dark"] [data-theme~="classic"]:where(:not([data-mode], [data-mode="light"] [data-theme~="classic"])) {
    /* Lighter blue for dark mode contrast */
    --lightness-primary: 60%;
    --chroma-primary: 0.10;

    /* Reduced tint chroma for warm-tinted surfaces */
    --chroma-surface-tint: 0.015;

    /* Custom surface lightness (differs from core defaults) */
    --color-background: oklch(10% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface: oklch(14% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface-raised: oklch(18% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface-sunken: oklch(8% var(--chroma-surface-tint) var(--hue-primary));
    --color-surface-alt: oklch(16% var(--chroma-surface-tint) var(--hue-primary));
    --color-text: oklch(92% 0.01 var(--hue-primary));
    --color-text-muted: oklch(70% var(--chroma-surface-tint) var(--hue-primary));
    --color-border: oklch(28% var(--chroma-surface-tint) var(--hue-primary));
    --color-border-strong: oklch(48% var(--chroma-surface-tint) var(--hue-primary));
    --color-border-muted: oklch(22% var(--chroma-surface-tint) var(--hue-primary));

    /* Softer gold accent in dark mode */
    --lightness-accent: 70%;
    --chroma-accent: 0.12;

    /* Slightly stronger shadows for dark mode */
    --shadow-xs: 0 1px 2px 0 oklch(0% 0 0 / 0.15);
    --shadow-s: 0 1px 3px 0 oklch(0% 0 0 / 0.2),
                 0 1px 2px -1px oklch(0% 0 0 / 0.12);
    --shadow-m: 0 3px 6px -1px oklch(0% 0 0 / 0.25),
                 0 2px 4px -2px oklch(0% 0 0 / 0.2);
    --shadow-l: 0 8px 12px -2px oklch(0% 0 0 / 0.3),
                 0 4px 6px -3px oklch(0% 0 0 / 0.2);
    --shadow-xl: 0 16px 20px -4px oklch(0% 0 0 / 0.35),
                 0 8px 10px -5px oklch(0% 0 0 / 0.2);
    --shadow-2xl: 0 24px 40px -8px oklch(0% 0 0 / 0.4);
  }

  /* System dark with no data-mode (CSS-only consumers): mirror the dark block. */
  @media (prefers-color-scheme: dark) {
    :root[data-theme~="classic"]:not([data-mode="light"]),
    [data-theme~="classic"]:not([data-mode="light"]):where(:not([data-mode="light"] *)) {
      /* Lighter blue for dark mode contrast */
      --lightness-primary: 60%;
      --chroma-primary: 0.10;

      /* Reduced tint chroma for warm-tinted surfaces */
      --chroma-surface-tint: 0.015;

      /* Custom surface lightness (differs from core defaults) */
      --color-background: oklch(10% var(--chroma-surface-tint) var(--hue-primary));
      --color-surface: oklch(14% var(--chroma-surface-tint) var(--hue-primary));
      --color-surface-raised: oklch(18% var(--chroma-surface-tint) var(--hue-primary));
      --color-surface-sunken: oklch(8% var(--chroma-surface-tint) var(--hue-primary));
      --color-surface-alt: oklch(16% var(--chroma-surface-tint) var(--hue-primary));
      --color-text: oklch(92% 0.01 var(--hue-primary));
      --color-text-muted: oklch(70% var(--chroma-surface-tint) var(--hue-primary));
      --color-border: oklch(28% var(--chroma-surface-tint) var(--hue-primary));
      --color-border-strong: oklch(48% var(--chroma-surface-tint) var(--hue-primary));
      --color-border-muted: oklch(22% var(--chroma-surface-tint) var(--hue-primary));

      /* Softer gold accent in dark mode */
      --lightness-accent: 70%;
      --chroma-accent: 0.12;

      /* Slightly stronger shadows for dark mode */
      --shadow-xs: 0 1px 2px 0 oklch(0% 0 0 / 0.15);
      --shadow-s: 0 1px 3px 0 oklch(0% 0 0 / 0.2),
                   0 1px 2px -1px oklch(0% 0 0 / 0.12);
      --shadow-m: 0 3px 6px -1px oklch(0% 0 0 / 0.25),
                   0 2px 4px -2px oklch(0% 0 0 / 0.2);
      --shadow-l: 0 8px 12px -2px oklch(0% 0 0 / 0.3),
                   0 4px 6px -3px oklch(0% 0 0 / 0.2);
      --shadow-xl: 0 16px 20px -4px oklch(0% 0 0 / 0.35),
                   0 8px 10px -5px oklch(0% 0 0 / 0.2);
      --shadow-2xl: 0 24px 40px -8px oklch(0% 0 0 / 0.4);
    }
  }
}
