/* anchor: Link styling with variants and auto-detection */

a {
  color: var(--color-interactive);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.15em;
  transition:
    color var(--duration-fast) var(--ease-default),
    text-decoration-thickness var(--duration-fast) var(--ease-default);

  &:hover {
    text-decoration-thickness: 2px;
  }

  &:focus-visible {
    outline: var(--border-width-medium) solid var(--color-interactive);
    outline-offset: var(--border-width-thin);
    border-radius: var(--radius-s);
  }

  /* Remove underline for links wrapping block elements */
  &:has(> img),
  &:has(> picture),
  &:has(> figure),
  &:has(> layout-card) {
    text-decoration: none;
  }
}

/* ===========================================
   Link Variants (data-variant API)
   =========================================== */

/* Muted link - less prominent, for secondary navigation */
a[data-variant="muted"] {
  color: var(--color-text-muted);

  &:hover {
    color: var(--color-text);
  }
}

/* Plain link - no underline by default, appears on hover */
a[data-variant="plain"] {
  text-decoration: none;

  &:hover {
    text-decoration: underline;
  }
}

/* ===========================================
   Auto-Detect Link Types
   Use data-no-icon to suppress auto-icons
   =========================================== */

/* External links - auto-detect http(s) links.
 * Skip when rel~="external" is present — src/utils/links.css handles
 * those, and double-applying the pseudo-element would render two arrows.
 */
a[href^="http"]:where(:not([data-no-icon]):not([rel~="external"]))::after,
a[href^="//"]:where(:not([data-no-icon]):not([rel~="external"]))::after {
  content: "↗";
  content: "↗" / "";
  font-size: 0.9em;
  font-style: normal;
  opacity: 0.7;
  display: inline-block;
  text-decoration: none;
  padding-inline-start: 0.5em;
}

/* Download links */
a[download]:where(:not([data-no-icon]))::after {
  content: "↓";
  content: "↓" / "";
  font-size: 0.9em;
  font-style: normal;
  opacity: 0.7;
  display: inline-block;
  text-decoration: none;
  padding-inline-start: 0.5em;
}

/* Email links */
a[href^="mailto"]:where(:not([data-no-icon]))::before {
  content: "\2709\00A0"; /* envelope + NBSP */
  content: "\2709\00A0" / "";
  font-style: normal;
  opacity: 0.7;
}

/* Phone links */
a[href^="tel"]:where(:not([data-no-icon]))::before {
  content: "\260E\00A0"; /* phone + NBSP */
  content: "\260E\00A0" / "";
  font-style: normal;
  opacity: 0.7;
}

/* PDF links (a download link to a PDF keeps the download arrow) */
a[href$=".pdf"]:where(:not([data-no-icon]):not([download]))::after {
  content: "PDF";
  font-size: 0.7em;
  font-weight: 600;
  opacity: 0.6;
  display: inline-block;
  text-decoration: none;
  padding-inline-start: 0.4em;
  vertical-align: super;
}

/* ===========================================
   Manual Link Icons
   Use <icon-wc> inside links for custom icons
   =========================================== */

/* Icon inside link - removes underline, adds spacing */
a > icon-wc {
  text-decoration: none;
  margin-inline-end: 0.35em;
  vertical-align: -0.125em; /* Optical alignment */
}

/* Icon after link text (trailing) */
a > icon-wc:last-child {
  margin-inline-end: 0;
  margin-inline-start: 0.35em;
}

/* ===========================================
   Context Overrides
   Links in navigation contexts don't show icons
   =========================================== */

/* Auto-detect selectors, wrapped in :is() so the override outranks them */
:is(nav, header, footer) a:is([href^="http"], [href^="//"], [download], [href$=".pdf"])::after,
:is(nav, header, footer) a:is([href^="mailto"], [href^="tel"])::before {
  content: none;
}

/* An authored <icon-wc> replaces the auto-detected glyph */
a:is([href^="mailto"], [href^="tel"]):has(> icon-wc)::before,
a:is([href^="http"], [href^="//"], [download], [href$=".pdf"]):has(> icon-wc)::after {
  content: none;
}

/* Icon-only links — no external indicator or trailing margin */
a:has(> icon-wc:only-child)::after,
a:has(> svg:only-child)::after,
a:has(> img:only-child)::after {
  content: none;
}

a > icon-wc:only-child {
  margin-inline: 0;
}

/* ===========================================
   Button-Styled Links
   Use class="button" on <a> for CTA links
   =========================================== */

/* Button-styled link - overrides anchor defaults. Colour comes from the
   button rule (--btn-color / --_text) so a.button and <button> match. */
a.button {
  text-decoration: none;

  &:hover {
    text-decoration: none;
  }

  /* Suppress auto-icons on button-styled links */
  &:is([href^="http"], [href^="//"], [download], [href$=".pdf"])::after,
  &:is([href^="mailto"], [href^="tel"])::before {
    content: none;
  }
}

